<?php
namespace App\Models;use App\Models\Concerns\ProtectsOfficialRegister;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
final class Partner extends Model{use HasUuids,ProtectsOfficialRegister;protected$fillable=['tenant_id','party_id','type','licence_number','licence_expires_on','status','compliance','canonical_id','slug','legal_name','trade_name','regulator_sequence','data_origin','source_authority','reference_year','regulatory_status','register_source','country_code','is_official_register','is_demo'];protected function casts():array{return['licence_expires_on'=>'date','compliance'=>'array','is_official_register'=>'boolean','is_demo'=>'boolean','regulator_sequence'=>'integer','reference_year'=>'integer'];}public function tenant():BelongsTo{return$this->belongsTo(Tenant::class);}public function party():BelongsTo{return$this->belongsTo(Party::class);}public function licences():HasMany{return$this->hasMany(PartnerLicence::class);}public function intermediaryAuthorizations():HasMany{return$this->hasMany(IntermediaryAuthorization::class);}}
